import { SummaryPanel } from '../summary/summary';
import { ClassicSummaryPanel } from '../summary/classic-summary';
import { VoidReasonsPanel } from '../void-reasons/void-reasons';

// The one screen: sign in by name, then choose a sheet by id. Everything else is kept per sheet.
@Component({
  selector: 'app-home',
  hostDirectives: [LocaleFigures],
  imports: [ActivityPanel, AuditPanel, BulkOpen, BulkReassign, BulkRedate, BulkSettle, BulkVoid, ClaimTemplatesPanel, ClassicSummaryPanel, CrewsPanel, GeneratePlans, HeaderCounters, HolidaysPanel, ImportPeople, ImportRates, NotesPanel, PasteClaims, PeopleList, PeriodsPanel, PoolsPanel, RatesPanel, SearchPanel, SettingsPanel, SummaryPanel, VoidReasonsPanel],
  template: `
    @if (session.user(); as user) {
      @if (session.sheetId()) {
        <app-header />
      }
      <section aria-label="Session" data-testid="session-bar">
        <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>
        <form (submit)="saveLocale($event)">
          <label for="user-locale">Your locale</label>
          <select
            id="user-locale"
            data-testid="user-locale"
            [value]="localeInput()"
            (change)="localeInput.set(value($event)); localeError.set(null)"
          >
            @for (l of locales; track l) {
              <option [value]="l" [selected]="l === localeInput()">{{ l }}</option>
            }
          </select>
          <button type="submit" data-testid="user-locale-save" [disabled]="savingLocale()">Save locale</button>
        </form>
        <p>Locale: <strong data-testid="user-locale-current">{{ userLocale.locale() }}</strong></p>
        @if (localeError(); as err) {
          <p role="alert" data-testid="user-locale-error">{{ err }}</p>
        }
        <form (submit)="load($event)">
          <label for="sheet-id-input">Sheet id</label>
          <input
            id="sheet-id-input"
            data-testid="sheet-id-input"
            [value]="sheetInput()"
            (input)="sheetInput.set(value($event)); sheetError.set(null)"
          />
          <button type="submit" data-testid="sheet-load" [disabled]="loading()">Load</button>
        </form>
        @if (sheetError(); as err) {
